"""
Run the full pipeline and return the (1,1) entry (index [0, 0]) of A f(A^{-1} B), f = natural log, B = A0 @ A0.

Orchestrates the full two-stage chain using the six functions implemented in the previous steps: reconstruct the quadratic matrix polynomial's coefficient matrices A0, A1, A2 from a standard pair (X, J) and its compatible parameter matrix Gamma, then build a severely ill-conditioned positive definite matrix A from A2's structure with the prescribed condition number, evaluate the resulting matrix function of the pencil (A, B) for B = A0 A0, and report the (1,1) entry (index [0, 0]) of the result. The available step functions are reconstruct_gamma, leading_coefficient_A2, linear_coefficient_A1, constant_coefficient_A0, build_conditioned_pencil, and pencil_matrix_function; determining the correct arguments and composition order for each is part of this step.

Returns
-------
The (1,1) entry (index [0, 0]) of A f(A^{-1} B).
"""

# =============================================================================
# FUNCTION SIGNATURE (shown to the LLM)
# =============================================================================

def compute_pencil_entry(J: "np.ndarray", X: "np.ndarray", condition_number: float) -> float:
    """Run the full pipeline and return the (1,1) entry (index [0, 0]) of
    A f(A^{-1} B), f = natural log, B = A0 @ A0.

    Parameters
    ----------
    J : np.ndarray
        (18, 18) real symmetric matrix.
    X : np.ndarray
        (9, 18) real matrix.
    condition_number : float
        Prescribed condition number for the Stage 2 matrix A (> 1).

    Returns
    -------
    entry : float
        The (1,1) entry (index [0, 0]) of A f(A^{-1} B).

    Raises
    ------
    ValueError
        If condition_number is not strictly greater than 1, or if any
        of the intermediate reconstruction/construction steps reject
        J, X, or the derived matrices as invalid (see the individual
        step functions for their specific conditions).
    """
    return 0.0  # placeholder

# =============================================================================
# GOLD SOLUTION
# =============================================================================

import numpy as np


def _oracle_compute_pencil_entry(J: "np.ndarray", X: "np.ndarray", condition_number: float) -> float:
    Gamma = _oracle_reconstruct_gamma(J, X)
    A2 = _oracle_leading_coefficient_A2(J, X, Gamma)
    A1 = _oracle_linear_coefficient_A1(J, X, Gamma, A2)
    A0 = _oracle_constant_coefficient_A0(J, X, Gamma, A1, A2)
    A = _oracle_build_conditioned_pencil(A2, condition_number)
    result = _oracle_pencil_matrix_function(A, A0)
    return float(result[0, 0])

